  async restart() {
    if (this.child) {
      this._set('stopping', '正在重启本地 Runtime')
      this.child.kill()
      this.child = undefined
      await delay(800)
    } else if (await this._applicationReady()) {
      this._set('ready', 'Runtime 已在后台运行；页面已重新连接')
      return this.snapshot()
    }
    return this.start()
  }

