      "path": "plugins/dsh-portfolio-os/cordis.patch.yml",
      "content": "- insert:\n    - id: dsh-portfolio-os\n      name: dsh-portfolio-os\n      config:\n        port: 41731\n        autoStart: true\n        keepRunningOnExit: true\n        startupTimeoutSeconds: 90\n"
